INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1026447, 123113, 17148, '<td valign="top">Love the photo, and the time piece, would love to own something like that.</td>', 'Love the photo, and the time piece, would love to own something like that.', '2004-11-22 00:13:31.000000', NULL, 1),
(1026450, 122528, 27842, '<td valign="top">Excellent capture of color and texture</td>', 'Excellent capture of color and texture', '2004-11-22 00:14:48.000000', NULL, 1),
(1026451, 122748, 27842, '<td valign="top">Stunning detail and color</td>', 'Stunning detail and color', '2004-11-22 00:15:19.000000', NULL, 1),
(1026464, 123146, 25873, '<td valign="top">In Death Valley right?  What an amazing place...</td>', 'In Death Valley right?  What an amazing place...', '2004-11-22 00:18:34.000000', NULL, 1),
(1026468, 122983, 3102, '<td valign="top">Curious to see how this was done legally...</td>', 'Curious to see how this was done legally...', '2004-11-22 00:19:31.000000', NULL, 1),
(1026489, 123004, 23294, '<td valign="top">I really enjoy the idea of this photo.  While not the only ice melting picture, I felt this was very well photographed.  The lighting is great, nice and calm feeling.  The only thing is that the puddle should be growing towards the right.  That doesn''t affect the score though because it would look funny without this nice balance.  8.</td>', 'I really enjoy the idea of this photo.  While not the only ice melting picture, I felt this was very well photographed.  The lighting is great, nice and calm feeling.  The only thing is that the puddle should be growing towards the right.  That doesn''t affect the score though because it would look funny without this nice balance.  8.', '2004-11-22 00:27:41.000000', NULL, 1),
(1026495, 122699, 23294, '<td valign="top">Very cool idea, past meets present.  Love the feel ove the old half.  The new seems a little soft, probably because the filtering around her.  Overall i really like it. 8.</td>', 'Very cool idea, past meets present.  Love the feel ove the old half.  The new seems a little soft, probably because the filtering around her.  Overall i really like it. 8.', '2004-11-22 00:29:17.000000', NULL, 1),
(1026498, 123103, 25873, '<td valign="top">Perfect display of "passing of time".  Great composition!</td>', 'Perfect display of "passing of time".  Great composition!', '2004-11-22 00:29:36.000000', NULL, 1),
(1026502, 123015, 25873, '<td valign="top">Amazing lighting and focus.  Perfectly meets the theme, one of the best of the challenge.</td>', 'Amazing lighting and focus.  Perfectly meets the theme, one of the best of the challenge.', '2004-11-22 00:30:35.000000', NULL, 1),
(1026504, 122186, 23294, '<td valign="top">Really good photo here.  I love the lighting, how the left older side is much darker.  Maybe symbolic of a negativeness of growing older.  Good idea! 7.</td>', 'Really good photo here.  I love the lighting, how the left older side is much darker.  Maybe symbolic of a negativeness of growing older.  Good idea! 7.', '2004-11-22 00:30:52.000000', NULL, 1),
(1026506, 122783, 23294, '<td valign="top">I''m a sucker for selective desat.  Nice bright colors on the leaves and an awesome backround for them. 7.</td>', 'I''m a sucker for selective desat.  Nice bright colors on the leaves and an awesome backround for them. 7.', '2004-11-22 00:31:36.000000', NULL, 1),
(1026514, 122983, 23294, '<td valign="top">Intersting photo.  Love the half empty effect.  Is it two mixed photos?  Not a big fan of the beer can in the back, just looks like trash laying about.  7.</td>', 'Intersting photo.  Love the half empty effect.  Is it two mixed photos?  Not a big fan of the beer can in the back, just looks like trash laying about.  7.', '2004-11-22 00:34:06.000000', NULL, 1),
(1026515, 122657, 18838, '<td valign="top">greetings fellow san diegan ...</td>', 'greetings fellow san diegan ...', '2004-11-22 00:34:18.000000', NULL, 1),
(1026518, 121203, 25873, '<td valign="top">Beautiful picture, almost looks like drawing.  This picture could have been taken anytime in the last few thousand years without any distinguishing difference, well done.</td>', 'Beautiful picture, almost looks like drawing.  This picture could have been taken anytime in the last few thousand years without any distinguishing difference, well done.', '2004-11-22 00:34:58.000000', NULL, 1),
(1026519, 123170, 19982, '<td valign="top">I love the blurred effect with tack sharp image at the end.  Tha means you used 2nd curtain sync...  something not everyone will know about.  Beautiful image and well done.  I''ll be back later to see if this lands in the top 10.  :-)</td>', 'I love the blurred effect with tack sharp image at the end.  Tha means you used 2nd curtain sync...  something not everyone will know about.  Beautiful image and well done.  I''ll be back later to see if this lands in the top 10.  :-)', '2004-11-22 00:35:15.000000', NULL, 1),
(1026520, 122466, 25873, '<td valign="top">Great sunrise capture, beautiful colours.</td>', 'Great sunrise capture, beautiful colours.', '2004-11-22 00:35:25.000000', NULL, 1),
(1026525, 123027, 28261, '<td valign="top">Have to give this high marks, just for the fact that you managed to really illustrate time passing.  Great shot, reminds me of a clock, without the hands great subject too.</td>', 'Have to give this high marks, just for the fact that you managed to really illustrate time passing.  Great shot, reminds me of a clock, without the hands great subject too.', '2004-11-22 00:38:09.000000', NULL, 1),
(1026528, 123101, 10432, '<td valign="top">This is too funny!!</td>', 'This is too funny!!', '2004-11-22 00:39:00.000000', NULL, 1),
(1026532, 122699, 8891, '<td valign="top">Perfect set up and execution. Love the setting and the costume on the older generation. Like the tone used.  GREAT idea!    Already my fav.  Good luck!</td>', 'Perfect set up and execution. Love the setting and the costume on the older generation. Like the tone used.  GREAT idea!    Already my fav.  Good luck!', '2004-11-22 00:40:39.000000', NULL, 1),
(1026539, 122891, 19982, '<td valign="top">It''s hard to get the idea of "passing time" from this image, even with the title ... but gosh, it''s a gorgeous image!  I''ll give it a little bump just cuz I like it!  :-)</td>', 'It''s hard to get the idea of "passing time" from this image, even with the title ... but gosh, it''s a gorgeous image!  I''ll give it a little bump just cuz I like it!  :-)', '2004-11-22 00:43:49.000000', NULL, 1),
(1026540, 121663, 326, '<td valign="top">This is GREAT!! Excellent job!</td>', 'This is GREAT!! Excellent job!', '2004-11-22 00:44:05.000000', NULL, 1),
(1026544, 122107, 28261, '<td valign="top">Very cool colors, placement and cropping.  Unsure how I feel about the blue edging, but this is first pass and I''ll be back for a couple more visits.</td>', 'Very cool colors, placement and cropping.  Unsure how I feel about the blue edging, but this is first pass and I''ll be back for a couple more visits.', '2004-11-22 00:46:04.000000', NULL, 1),
(1026547, 121860, 28261, '<td valign="top">Although we all expected the slew of watches/clocks, I really like the choice of the multi-function faces.  The crop is great and balanced and the time even lends to the best placement as it cuts off the left 3rd and top 3rd.  Great shot.</td>', 'Although we all expected the slew of watches/clocks, I really like the choice of the multi-function faces.  The crop is great and balanced and the time even lends to the best placement as it cuts off the left 3rd and top 3rd.  Great shot.', '2004-11-22 00:48:26.000000', NULL, 1),
(1026549, 122956, 19982, '<td valign="top">At least this one manages to truly convey the passing of time!  :-)<br/> <br/>I like the lighting and composition.  Good luck in the challenge!</td>', 'At least this one manages to truly convey the passing of time!  :-) I like the lighting and composition.  Good luck in the challenge!', '2004-11-22 00:49:43.000000', NULL, 1),
(1026550, 121666, 18799, '<td valign="top">more importantly, you forgot to remove your shorts!</td>', 'more importantly, you forgot to remove your shorts!', '2004-11-22 00:50:29.000000', NULL, 1),
(1026552, 123106, 28261, '<td valign="top">Great use of 3rds, simplicity and crop.  Took me a few to catch how the small clock was so perfectly boxed.  This must have been a bear to shoot ''just right'' and you''ve done a fine job of doing just that.</td>', 'Great use of 3rds, simplicity and crop.  Took me a few to catch how the small clock was so perfectly boxed.  This must have been a bear to shoot ''just right'' and you''ve done a fine job of doing just that.', '2004-11-22 00:51:00.000000', NULL, 1),
(1026556, 123128, 28261, '<td valign="top">I know just how hard this technique is with long exposure ccd, to reduce noise.   You''ve done a great job of pinpointing the focus and retaining the colors.  Not sure if you used layering to increase the saturation or just boosted in PS, but they work very well.<br/> .. To reduce the red ccd noise, boost the shadow a few notches, it does not always eliminate 100% of them, but greatly reduces the effect.  Throw on a sharpen after to bring the true light sources back to their brilliance.</td>', 'I know just how hard this technique is with long exposure ccd, to reduce noise.   You''ve done a great job of pinpointing the focus and retaining the colors.  Not sure if you used layering to increase the saturation or just boosted in PS, but they work very well. .. To reduce the red ccd noise, boost the shadow a few notches, it does not always eliminate 100% of them, but greatly reduces the effect.  Throw on a sharpen after to bring the true light sources back to their brilliance.', '2004-11-22 00:57:32.000000', NULL, 1),
(1026576, 122845, 15511, '<td valign="top">Good interpretation, the lighter is distracting.</td>', 'Good interpretation, the lighter is distracting.', '2004-11-22 01:12:23.000000', NULL, 1),
(1026585, 122887, 24065, '<td valign="top">beautiful lady and beautiful photo  BOL</td>', 'beautiful lady and beautiful photo  BOL', '2004-11-22 01:16:57.000000', NULL, 1),
(1026598, 121892, 15511, '<td valign="top">Looks a little fuzzy. Very "period looking" image. I like it.</td>', 'Looks a little fuzzy. Very "period looking" image. I like it.', '2004-11-22 01:22:24.000000', NULL, 1),
(1026601, 122744, 15511, '<td valign="top">Needs just a little more depth of field.</td>', 'Needs just a little more depth of field.', '2004-11-22 01:24:12.000000', NULL, 1),
(1026616, 123022, 22734, '<td valign="top">This image is on the money with great expression and the changes in time where such a publication reduces itself to catch the beat that need not be really addressed. more of a playboy topic. great message. You have my 9</td>', 'This image is on the money with great expression and the changes in time where such a publication reduces itself to catch the beat that need not be really addressed. more of a playboy topic. great message. You have my 9', '2004-11-22 01:41:06.000000', NULL, 1),
(1026622, 122186, 22734, '<td valign="top">Where do you get such handsome models.lol Great shot displaying great creativity. You have my 8 for this fomidable study, good luck.</td>', 'Where do you get such handsome models.lol Great shot displaying great creativity. You have my 8 for this fomidable study, good luck.', '2004-11-22 01:43:41.000000', NULL, 1),
(1026635, 122186, 93, '<td valign="top">I simply cannot *WAIT* to see how you pulled this off..  Make up? Hair dye? It''s brilliant!  I had the same type of idea, but just couldn''t think of a way to pull it off.<br/> <br/>Very well executed. I love the negative space, really adds an element to the photo. To me, it says, "I await my future, but I have a lot of it to go through first".<br/> <br/> <br/>10 from me.<br/> <br/>(Is this Colda? Looks like his profile pic.)</td>', 'I simply cannot *WAIT* to see how you pulled this off..  Make up? Hair dye? It''s brilliant!  I had the same type of idea, but just couldn''t think of a way to pull it off. Very well executed. I love the negative space, really adds an element to the photo. To me, it says, "I await my future, but I have a lot of it to go through first".  10 from me. (Is this Colda? Looks like his profile pic.)', '2004-11-22 02:01:19.000000', NULL, 1),
(1026640, 122816, 93, '<td valign="top">Gorgeous to look at, but I don''t really feel the time passing here.  It more conveys time *stopping* to me.</td>', 'Gorgeous to look at, but I don''t really feel the time passing here.  It more conveys time *stopping* to me.', '2004-11-22 02:13:10.000000', NULL, 1),
(1026641, 123004, 93, '<td valign="top">hahaha.. Remind me after the challenge is over and I''ll show you the version I did of a shot like this (your''s is way better).   Good job with the lighting.. and the composition is fantastic.</td>', 'hahaha.. Remind me after the challenge is over and I''ll show you the version I did of a shot like this (your''s is way better).   Good job with the lighting.. and the composition is fantastic.', '2004-11-22 02:16:15.000000', NULL, 1),
(1026668, 122851, 22479, '<td valign="top">I think this photograph works well for this theme. Stamen appear to be slightly out of focus but the colors, framing, and detail otherwise is excellent. One of the stronger entries.</td>', 'I think this photograph works well for this theme. Stamen appear to be slightly out of focus but the colors, framing, and detail otherwise is excellent. One of the stronger entries.', '2004-11-22 03:10:10.000000', NULL, 1),
(1026669, 123048, 22479, '<td valign="top">Good idea for this challenge. I actually like the way you framed this shot. Good detail and focus.</td>', 'Good idea for this challenge. I actually like the way you framed this shot. Good detail and focus.', '2004-11-22 03:11:10.000000', NULL, 1),
(1026671, 122217, 22479, '<td valign="top">Very nostalgic feel to this photograph. I think the reflections off the water add a nice glow and effective silhouette to the foreground subjects. The sky is interesting as are the forested hills in the backdrop. Overall I think this is my favorite of the bunch. 10</td>', 'Very nostalgic feel to this photograph. I think the reflections off the water add a nice glow and effective silhouette to the foreground subjects. The sky is interesting as are the forested hills in the backdrop. Overall I think this is my favorite of the bunch. 10', '2004-11-22 03:15:11.000000', NULL, 1),
(1026672, 123020, 22479, '<td valign="top">I think the colors in this shot are great. One of the stronger entries for sure. 8</td>', 'I think the colors in this shot are great. One of the stronger entries for sure. 8', '2004-11-22 03:16:14.000000', NULL, 1),
(1026673, 122699, 22479, '<td valign="top">This is I think the best use of selective desaturation I''ve seen in a while. Fits the theme perfectly. 9</td>', 'This is I think the best use of selective desaturation I''ve seen in a while. Fits the theme perfectly. 9', '2004-11-22 03:17:16.000000', NULL, 1),
(1026674, 123091, 22479, '<td valign="top">Good framing and detail. Desat and toning done to good effect. One of the stronger entries in my book.</td>', 'Good framing and detail. Desat and toning done to good effect. One of the stronger entries in my book.', '2004-11-22 03:19:18.000000', NULL, 1),
(1026678, 122354, 22479, '<td valign="top">Effective use of dodging and burning. Framed nicely.</td>', 'Effective use of dodging and burning. Framed nicely.', '2004-11-22 03:20:09.000000', NULL, 1),
(1026680, 123101, 22479, '<td valign="top">This very clever shot could have been wonderful in either this, or the next challenge (Humor II). Brought a smile to my face, one of the stronger entries.</td>', 'This very clever shot could have been wonderful in either this, or the next challenge (Humor II). Brought a smile to my face, one of the stronger entries.', '2004-11-22 03:21:22.000000', NULL, 1),
(1026682, 121884, 22479, '<td valign="top">Effective use of space. I like the way you framed this shot, though some will probably disagree.</td>', 'Effective use of space. I like the way you framed this shot, though some will probably disagree.', '2004-11-22 03:22:09.000000', NULL, 1),
(1026684, 123015, 22479, '<td valign="top">Sharp, detailed, well focused. Burned nicely.</td>', 'Sharp, detailed, well focused. Burned nicely.', '2004-11-22 03:22:53.000000', NULL, 1),
(1026685, 123165, 22479, '<td valign="top">Creative, I like the perspective, and the framing.</td>', 'Creative, I like the perspective, and the framing.', '2004-11-22 03:23:32.000000', NULL, 1),
(1026686, 123103, 22479, '<td valign="top">Very nostalgic.</td>', 'Very nostalgic.', '2004-11-22 03:24:04.000000', NULL, 1),
(1026687, 123002, 22479, '<td valign="top">Framed nicely, great motion blur. Fits theme perfectly.</td>', 'Framed nicely, great motion blur. Fits theme perfectly.', '2004-11-22 03:24:45.000000', NULL, 1),
(1026690, 122954, 22479, '<td valign="top">This looks a lot like "Into the Darkness". I think you have a very creative entry. My only suggestion would have been to show progressively more wax dripping down the candles.</td>', 'This looks a lot like "Into the Darkness". I think you have a very creative entry. My only suggestion would have been to show progressively more wax dripping down the candles.', '2004-11-22 03:26:41.000000', NULL, 1),
(1026691, 121554, 22479, '<td valign="top">Nice blur effect.</td>', 'Nice blur effect.', '2004-11-22 03:27:02.000000', NULL, 1),
(1026695, 122380, 22479, '<td valign="top">Exposure is on the money. Nostalgic.</td>', 'Exposure is on the money. Nostalgic.', '2004-11-22 03:28:38.000000', NULL, 1),
(1026698, 123051, 22479, '<td valign="top">Clever and effective. Wonderful exposure on the stained glass.</td>', 'Clever and effective. Wonderful exposure on the stained glass.', '2004-11-22 03:29:05.000000', NULL, 1),
(1026700, 122891, 22479, '<td valign="top">Nice dramatic effect with the darkened water.</td>', 'Nice dramatic effect with the darkened water.', '2004-11-22 03:30:01.000000', NULL, 1),
(1026704, 123064, 22479, '<td valign="top">Nice framing. Dark mood created by the tombstones which you have exposed very well. Could be a setting for a sequel to Psycho.</td>', 'Nice framing. Dark mood created by the tombstones which you have exposed very well. Could be a setting for a sequel to Psycho.', '2004-11-22 03:31:59.000000', NULL, 1),
(1026706, 122144, 22479, '<td valign="top">Clever use of multiple exposures.</td>', 'Clever use of multiple exposures.', '2004-11-22 03:32:24.000000', NULL, 1),
(1026712, 122956, 22479, '<td valign="top">I like the way you framed and composed this shot. No reference to how tall that hourglass might be...could be an inch tall or several meters tall.</td>', 'I like the way you framed and composed this shot. No reference to how tall that hourglass might be...could be an inch tall or several meters tall.', '2004-11-22 03:35:03.000000', NULL, 1),
(1026713, 123009, 22479, '<td valign="top">Very nostalgic.</td>', 'Very nostalgic.', '2004-11-22 03:35:18.000000', NULL, 1),
(1026719, 123146, 22479, '<td valign="top">Nice whirlpool. Not sure how this illustrates time passing other than exposure time. Sharp, detailed, framed well. B&amp;W/toning done tastefully.</td>', 'Nice whirlpool. Not sure how this illustrates time passing other than exposure time. Sharp, detailed, framed well. B&W/toning done tastefully.', '2004-11-22 03:36:48.000000', NULL, 1),
(1026720, 122433, 22479, '<td valign="top">I really like everything about this photo except for the selective desat. I think the exposure, lighting, and detail is excellent.</td>', 'I really like everything about this photo except for the selective desat. I think the exposure, lighting, and detail is excellent.', '2004-11-22 03:37:59.000000', NULL, 1),
(1026721, 123038, 22479, '<td valign="top">Nice exposure and motion blur.</td>', 'Nice exposure and motion blur.', '2004-11-22 03:38:46.000000', NULL, 1),
(1026724, 122783, 22479, '<td valign="top">I don''t like the way you stacked the leaves on top of each other. Otherwise, you chose a great backdrop. Sharp, detailed, well exposed.</td>', 'I don''t like the way you stacked the leaves on top of each other. Otherwise, you chose a great backdrop. Sharp, detailed, well exposed.', '2004-11-22 03:40:09.000000', NULL, 1),
(1026727, 122836, 22479, '<td valign="top">Excellent desaturation. Nice how you threw in a clock over in the corner as well.</td>', 'Excellent desaturation. Nice how you threw in a clock over in the corner as well.', '2004-11-22 03:41:37.000000', NULL, 1),
(1026729, 122028, 22479, '<td valign="top">Tastefully composed. Nice effect.</td>', 'Tastefully composed. Nice effect.', '2004-11-22 03:42:35.000000', NULL, 1),
(1026733, 121666, 22479, '<td valign="top">I guess everyone at one time or another can relate to this. Very humorous. <br/> <br/>Several distractors which I would like to point out: Focus is off...no part of the image is really in focus. The hairy legs are rather scary. The flash photography creates harsh light and prominent shadows. The subject''s head is out of the frame (I guess that''s understandable!), and finally the colors are somewhat muted.<br/> <br/>If it was not for the fact that your entry fits the theme perfectly, I would have ranked this rather low.</td>', 'I guess everyone at one time or another can relate to this. Very humorous.  Several distractors which I would like to point out: Focus is off...no part of the image is really in focus. The hairy legs are rather scary. The flash photography creates harsh light and prominent shadows. The subject''s head is out of the frame (I guess that''s understandable!), and finally the colors are somewhat muted. If it was not for the fact that your entry fits the theme perfectly, I would have ranked this rather low.', '2004-11-22 03:49:23.000000', NULL, 1),
(1026736, 122107, 22479, '<td valign="top">Not sure what this has to do with the challenge theme. The replaced colors give this an interesting and distinctive look. I imagine the original was sharp and in focus. <br/> <br/>Sorry but this is overall a poor entry.</td>', 'Not sure what this has to do with the challenge theme. The replaced colors give this an interesting and distinctive look. I imagine the original was sharp and in focus.  Sorry but this is overall a poor entry.', '2004-11-22 03:53:20.000000', NULL, 1),
(1026737, 122144, 29079, '<td valign="top">Great idea but I would have liked it more if the three clocks would actually show the time passing, rather than all three staying at 12:10</td>', 'Great idea but I would have liked it more if the three clocks would actually show the time passing, rather than all three staying at 12:10', '2004-11-22 03:57:41.000000', NULL, 1),
(1026759, 123092, 23478, '<td valign="top">Good color anfd excellent sense of time.</td>', 'Good color anfd excellent sense of time.', '2004-11-22 04:51:32.000000', NULL, 1),
(1026761, 122028, 23478, '<td valign="top">NIce photo, but it looks a bit wash outed and grainy.  Of course, that may be intentional, but it losses impact with me.</td>', 'NIce photo, but it looks a bit wash outed and grainy.  Of course, that may be intentional, but it losses impact with me.', '2004-11-22 04:53:53.000000', NULL, 1),
(1026762, 123166, 23478, '<td valign="top">Very nice capture of the motion and nice color on the water.</td>', 'Very nice capture of the motion and nice color on the water.', '2004-11-22 04:54:20.000000', NULL, 1),
(1026763, 122528, 23478, '<td valign="top">Nocely done macro.</td>', 'Nocely done macro.', '2004-11-22 04:55:22.000000', NULL, 1),
(1026764, 122759, 23478, '<td valign="top">The frame is huge and a bit of a distraction for me.</td>', 'The frame is huge and a bit of a distraction for me.', '2004-11-22 04:56:30.000000', NULL, 1),
(1026765, 122605, 23478, '<td valign="top">Nice sharp photo and cool lighting effect.  Well done.</td>', 'Nice sharp photo and cool lighting effect.  Well done.', '2004-11-22 04:56:53.000000', NULL, 1),
(1026766, 123018, 23478, '<td valign="top">Excellent portrait.</td>', 'Excellent portrait.', '2004-11-22 04:57:30.000000', NULL, 1),
(1026768, 122891, 23478, '<td valign="top">This image is too indistinct in relationsjhip to the challenge theme.  Great photo.  A multiple exposure of the moon would have been awesome.</td>', 'This image is too indistinct in relationsjhip to the challenge theme.  Great photo.  A multiple exposure of the moon would have been awesome.', '2004-11-22 04:59:13.000000', NULL, 1),
(1026769, 123048, 23478, '<td valign="top">Well done, conveys the theme with excellence.</td>', 'Well done, conveys the theme with excellence.', '2004-11-22 05:00:36.000000', NULL, 1),
(1026772, 123117, 23478, '<td valign="top">Nice image, the old house in the background works very well.</td>', 'Nice image, the old house in the background works very well.', '2004-11-22 05:04:14.000000', NULL, 1),
(1026773, 123153, 23478, '<td valign="top">Seems slightly OO, but well thought out.</td>', 'Seems slightly OO, but well thought out.', '2004-11-22 05:04:39.000000', NULL, 1),
(1026775, 122440, 8139, '<td valign="top">A technical shot!  Difficult to get in focus the 3 "times" . Well done anyway.</td>', 'A technical shot!  Difficult to get in focus the 3 "times" . Well done anyway.', '2004-11-22 05:06:25.000000', NULL, 1),
(1026779, 121590, 27482, '<td valign="top">Great cameras, both of them.  Funny though that the AE-1 is almost as old as I am.  Good shot but kindof flat, could use a little boost in contrast, also the backround above the 10D (20D?) is a bit distracting.</td>', 'Great cameras, both of them.  Funny though that the AE-1 is almost as old as I am.  Good shot but kindof flat, could use a little boost in contrast, also the backround above the 10D (20D?) is a bit distracting.', '2004-11-22 05:11:48.000000', NULL, 1),
