(1028147, 123062, 25464, '<td valign="top">This would have been really great if the sky hadn''t been blown out looking.  Great composition and idea. 6.</td>', 'This would have been really great if the sky hadn''t been blown out looking.  Great composition and idea. 6.', '2004-11-22 23:06:54.000000', NULL, 1),
(1028148, 123009, 25464, '<td valign="top">Nice take on the challenge.  I have this in my top 3.</td>', 'Nice take on the challenge.  I have this in my top 3.', '2004-11-22 23:07:20.000000', NULL, 1),
