(1028153, 123005, 25464, '<td valign="top">Interesting use of reflection. 8.</td>', 'Interesting use of reflection. 8.', '2004-11-22 23:12:40.000000', NULL, 1),
(1028157, 123130, 25464, '<td valign="top">I think this is a nice shot, but I do not see the connection to the challenge.  Maybe a little over the top on the processing as well. 5.</td>', 'I think this is a nice shot, but I do not see the connection to the challenge.  Maybe a little over the top on the processing as well. 5.', '2004-11-22 23:14:05.000000', NULL, 1),
(1028158, 123064, 25464, '<td valign="top">Very good use of black and white. Sharp and connected to the challenge.  No real wow, but good. 9.</td>', 'Very good use of black and white. Sharp and connected to the challenge.  No real wow, but good. 9.', '2004-11-22 23:15:00.000000', NULL, 1),
