INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1028213, 123020, 93, '<td valign="top">Damn.. this is almost exactly what I was trying to accomplish but couldn''t. (I didn''t have color though).  I''d love to know what you used for a surface/background.</td>', 'Damn.. this is almost exactly what I was trying to accomplish but couldn''t. (I didn''t have color though).  I''d love to know what you used for a surface/background.', '2004-11-23 00:11:27.000000', NULL, 1),
(1028221, 122741, 16301, '<td valign="top">Maybe a less centered composition would be better?</td>', 'Maybe a less centered composition would be better?', '2004-11-23 00:18:34.000000', NULL, 1),
(1028224, 121994, 16301, '<td valign="top">Maybe take it when the light is better? cuz the light here isn''t helping the subject...</td>', 'Maybe take it when the light is better? cuz the light here isn''t helping the subject...', '2004-11-23 00:20:05.000000', NULL, 1),
(1028227, 122186, 16301, '<td valign="top">Cool idea Bob!</td>', 'Cool idea Bob!', '2004-11-23 00:23:07.000000', NULL, 1),
(1028228, 123022, 16301, '<td valign="top">lol, very cool idea! I would suggest putting another magazine inside the Porno one, cuz it looks page-less here. Good luck...</td>', 'lol, very cool idea! I would suggest putting another magazine inside the Porno one, cuz it looks page-less here. Good luck...', '2004-11-23 00:25:45.000000', NULL, 1),
(1028233, 123115, 22970, '<td valign="top">Revised:<br/>Nicely done micro but the arrangements of each item is confusing and un-natural. The way you set your shot up draws my eye to the very sharp pencil. I think my eyes should be drawn towards the crossword puzzle. I believe you could have arranged the pencil in a better way. With that said you have a good photo here. You cropped well, good micro, nice dof, and good focus. Good Job!<br/></td>', 'Revised:Nicely done micro but the arrangements of each item is confusing and un-natural. The way you set your shot up draws my eye to the very sharp pencil. I think my eyes should be drawn towards the crossword puzzle. I believe you could have arranged the pencil in a better way. With that said you have a good photo here. You cropped well, good micro, nice dof, and good focus. Good Job!', '2004-11-23 00:34:35.000000', NULL, 1),
(1028235, 123119, 22970, '<td valign="top">You have achieved a good photograph here with good lighting, focus and detail, color, and good DOF. I feel you could composed your photograph a little better by having your pet facing the camera slightly giving the subject more depth, it would keep the subject from being so flat.</td>', 'You have achieved a good photograph here with good lighting, focus and detail, color, and good DOF. I feel you could composed your photograph a little better by having your pet facing the camera slightly giving the subject more depth, it would keep the subject from being so flat.', '2004-11-23 00:35:53.000000', NULL, 1),
(1028237, 122466, 22970, '<td valign="top">Nice silhouette but a bit out of focus. This could have been a good photo it focus would have been on. I dont know if you used a tripod or not but my guess is camera shake. Keep up the good work, this one was very close.<br/></td>', 'Nice silhouette but a bit out of focus. This could have been a good photo it focus would have been on. I dont know if you used a tripod or not but my guess is camera shake. Keep up the good work, this one was very close.', '2004-11-23 00:36:50.000000', NULL, 1),
(1028239, 123001, 22970, '<td valign="top">Where do I start? I see an item that is from the past but I dont see the time passing. I know its an interpretation thing but IMO it does exactly meet the challenge. You did however take a good close up shot with good detail and focus. Your lighting and white balance is good as well. I think it would have been better if you would of placed an current time controller in this shot with the cord connecting the two, the cord could of represented the passing of time. Just my 2 cents.</td>', 'Where do I start? I see an item that is from the past but I dont see the time passing. I know its an interpretation thing but IMO it does exactly meet the challenge. You did however take a good close up shot with good detail and focus. Your lighting and white balance is good as well. I think it would have been better if you would of placed an current time controller in this shot with the cord connecting the two, the cord could of represented the passing of time. Just my 2 cents.', '2004-11-23 00:37:11.000000', NULL, 1),
(1028269, 122741, 22928, '<td valign="top">Great play on the theme.</td>', 'Great play on the theme.', '2004-11-23 01:17:05.000000', NULL, 1),
(1028276, 122956, 29817, '<td valign="top">Wonderfully simple!</td>', 'Wonderfully simple!', '2004-11-23 01:33:36.000000', NULL, 1),
(1028310, 123153, 29607, '<td valign="top"></td>', '', '2004-11-23 02:19:27.000000', NULL, 1),
(1028382, 123101, 28742, '<td valign="top">Dude I love this song!  ;-)</td>', 'Dude I love this song!  ;-)', '2004-11-23 03:02:57.000000', NULL, 1),
(1028386, 121666, 28742, '<td valign="top">Not that I want to see it, but it would look less staged if his boxers were down. :-P</td>', 'Not that I want to see it, but it would look less staged if his boxers were down. :-P', '2004-11-23 03:08:25.000000', NULL, 1),
(1028387, 122903, 28742, '<td valign="top">Interesting idea. But I think you''re off base on 77 across.  ;-)</td>', 'Interesting idea. But I think you''re off base on 77 across.  ;-)', '2004-11-23 03:10:05.000000', NULL, 1),
(1028389, 122999, 28742, '<td valign="top">I saw this guy in concert!  ;-)</td>', 'I saw this guy in concert!  ;-)', '2004-11-23 03:12:59.000000', NULL, 1),
(1028390, 122744, 28742, '<td valign="top">Like the idea a lot, but I think I would''ve made it a wider, landscape formatted shot and maybe have the newest in focus. Hard to say until you see different variations. Good job though!</td>', 'Like the idea a lot, but I think I would''ve made it a wider, landscape formatted shot and maybe have the newest in focus. Hard to say until you see different variations. Good job though!', '2004-11-23 03:14:27.000000', NULL, 1),
(1028391, 122887, 28742, '<td valign="top">Great shot!</td>', 'Great shot!', '2004-11-23 03:16:04.000000', NULL, 1),
(1028392, 123030, 28742, '<td valign="top">How about "Condemnation"  ;-) Nice shot!</td>', 'How about "Condemnation"  ;-) Nice shot!', '2004-11-23 03:16:35.000000', NULL, 1),
(1028394, 123127, 28742, '<td valign="top">Needs more people bussing around.</td>', 'Needs more people bussing around.', '2004-11-23 03:16:59.000000', NULL, 1),
(1028395, 123099, 28742, '<td valign="top">Maybe swing slower or increase shutter speed to stop the watch in its path. Nice idea and decent shot!</td>', 'Maybe swing slower or increase shutter speed to stop the watch in its path. Nice idea and decent shot!', '2004-11-23 03:18:10.000000', NULL, 1),
(1028396, 123094, 28742, '<td valign="top">All we are is dust in the wind!  Cool.</td>', 'All we are is dust in the wind!  Cool.', '2004-11-23 03:19:01.000000', NULL, 1),
(1028397, 121892, 28742, '<td valign="top">Sure has that 19th century photo feel to it! Good shot.</td>', 'Sure has that 19th century photo feel to it! Good shot.', '2004-11-23 03:19:48.000000', NULL, 1),
(1028398, 123086, 28742, '<td valign="top">Are you going to finish those?  ;-)</td>', 'Are you going to finish those?  ;-)', '2004-11-23 03:20:15.000000', NULL, 1),
(1028399, 123003, 28742, '<td valign="top">Dang - you look like brothers!  ;-)  Curious about the technique...</td>', 'Dang - you look like brothers!  ;-)  Curious about the technique...', '2004-11-23 03:21:42.000000', NULL, 1),
(1028400, 123096, 28742, '<td valign="top">Definitely glad you didn''t make it BW. I like the colors and textures.</td>', 'Definitely glad you didn''t make it BW. I like the colors and textures.', '2004-11-23 03:22:29.000000', NULL, 1),
(1028401, 123022, 28742, '<td valign="top">Cool idea. Not sure why the reader''s eyes are looking shocked though and you could''ve roughed up the porno mag just a little on the edges.</td>', 'Cool idea. Not sure why the reader''s eyes are looking shocked though and you could''ve roughed up the porno mag just a little on the edges.', '2004-11-23 03:25:07.000000', NULL, 1),
(1028402, 123074, 28742, '<td valign="top">Right on! Groovy!  ;-)</td>', 'Right on! Groovy!  ;-)', '2004-11-23 03:25:53.000000', NULL, 1),
(1028403, 123001, 28742, '<td valign="top">Coulda been Atari.</td>', 'Coulda been Atari.', '2004-11-23 03:28:20.000000', NULL, 1),
(1028405, 121884, 28742, '<td valign="top">Would''ve been better with brush strokes on the wall (IMO). Good concept though.</td>', 'Would''ve been better with brush strokes on the wall (IMO). Good concept though.', '2004-11-23 03:29:23.000000', NULL, 1),
(1028408, 123168, 23478, '<td valign="top">This is a nice photo.  I think the impact would have been to greater using a green leaf and a dead, dry leaf.  But, this conveys the sense of passing time.  Good execution of your idea. 8.</td>', 'This is a nice photo.  I think the impact would have been to greater using a green leaf and a dead, dry leaf.  But, this conveys the sense of passing time.  Good execution of your idea. 8.', '2004-11-23 03:31:54.000000', NULL, 1),
(1028410, 122983, 28742, '<td valign="top">Assuming this didn''t violate the rules, I think it would have been equally effective if the glass was just plain empty with some foam at the bottom IMO.</td>', 'Assuming this didn''t violate the rules, I think it would have been equally effective if the glass was just plain empty with some foam at the bottom IMO.', '2004-11-23 03:32:40.000000', NULL, 1),
(1028411, 122186, 23478, '<td valign="top">Bob, nicely done.  You have expressed the passing of time ina very clear and obvious way, that is also creative.  9.</td>', 'Bob, nicely done.  You have expressed the passing of time ina very clear and obvious way, that is also creative.  9.', '2004-11-23 03:33:16.000000', NULL, 1),
(1028412, 122380, 28742, '<td valign="top">Hey - check a couple photos back - there''s a guy with a 5 O''clock shadow who could use your help.  ;-)</td>', 'Hey - check a couple photos back - there''s a guy with a 5 O''clock shadow who could use your help.  ;-)', '2004-11-23 03:34:13.000000', NULL, 1),
(1028414, 122746, 23478, '<td valign="top">INteresting photo, but for me, the siloeutte does not work well here.  It obscures instead of emphasizing the watch.</td>', 'INteresting photo, but for me, the siloeutte does not work well here.  It obscures instead of emphasizing the watch.', '2004-11-23 03:35:13.000000', NULL, 1),
(1028415, 122186, 28742, '<td valign="top">I''m just a stickler for time passing from left to right, so I would score it higher if the young guy was on the left and the old guy on the right. ...or you could have titled it "looking back on my youth" ;-)</td>', 'I''m just a stickler for time passing from left to right, so I would score it higher if the young guy was on the left and the old guy on the right. ...or you could have titled it "looking back on my youth" ;-)', '2004-11-23 03:37:02.000000', NULL, 1),
(1028417, 123146, 23478, '<td valign="top">To me, this is an almost great shot.  I think the big branch is a distraction.  Also, there is lack of contrast for using B&amp;W here.  I think that focusing more on the water flow and the contrast of the white water over the black rocks would have made a more powerful image.   6.</td>', 'To me, this is an almost great shot.  I think the big branch is a distraction.  Also, there is lack of contrast for using B&W here.  I think that focusing more on the water flow and the contrast of the white water over the black rocks would have made a more powerful image.   6.', '2004-11-23 03:41:06.000000', NULL, 1),
(1028418, 123151, 28742, '<td valign="top">Ok - it BOGGLES me how you came up with this idea so LATE in the challenge, but you deserve PRAISE and I can''t WAIT to hang this on my WALL once you put it up for SALE.   sorry couldn''t help myself.  ;-)</td>', 'Ok - it BOGGLES me how you came up with this idea so LATE in the challenge, but you deserve PRAISE and I can''t WAIT to hang this on my WALL once you put it up for SALE.   sorry couldn''t help myself.  ;-)', '2004-11-23 03:47:05.000000', NULL, 1),
(1028420, 122954, 28742, '<td valign="top">Slight improvement would be to see the drip buildup on the smaller candles. Nice shot though.</td>', 'Slight improvement would be to see the drip buildup on the smaller candles. Nice shot though.', '2004-11-23 03:50:37.000000', NULL, 1),
(1028421, 123048, 28742, '<td valign="top">I like it!</td>', 'I like it!', '2004-11-23 03:51:07.000000', NULL, 1),
(1028425, 121920, 28742, '<td valign="top">"...the moments that make up the dull day"   ...sorry, Pink Floyd flashback.  ;-)</td>', '"...the moments that make up the dull day"   ...sorry, Pink Floyd flashback.  ;-)', '2004-11-23 03:55:30.000000', NULL, 1),
(1028426, 123027, 28742, '<td valign="top">Wow - interesting. I never knew this memorial existed. Where is it?</td>', 'Wow - interesting. I never knew this memorial existed. Where is it?', '2004-11-23 03:57:40.000000', NULL, 1),
(1028427, 122437, 28742, '<td valign="top">If there was someone in the booth standing there staring at the receiver as if waiting for a call... maybe better?</td>', 'If there was someone in the booth standing there staring at the receiver as if waiting for a call... maybe better?', '2004-11-23 03:59:01.000000', NULL, 1),
