(1028432, 121884, 8624, '<td valign="top">you missed a spot...<br/> <br/>this is a great image. I love the wide expanse of negative space in the frame and the painter painter examining is work. very clever. good luck!</td>', 'you missed a spot... this is a great image. I love the wide expanse of negative space in the frame and the painter painter examining is work. very clever. good luck!', '2004-11-23 04:24:14.000000', NULL, 1),
(1028440, 122951, 29826, '<td valign="top">as always</td>', 'as always', '2004-11-23 05:33:29.000000', NULL, 1),
(1028444, 123130, 27287, '<td valign="top">The color is this photo is beautiful. Can''t get any better than this.</td>', 'The color is this photo is beautiful. Can''t get any better than this.', '2004-11-23 05:48:52.000000', NULL, 1),
(1028486, 123005, 29760, '<td valign="top">Good idea and implementation</td>', 'Good idea and implementation', '2004-11-23 07:01:55.000000', NULL, 1),
(1028488, 122699, 3306, '<td valign="top">Very good. The selective desaturation really accents the differences and passing of time. One of my favorites. 10</td>', 'Very good. The selective desaturation really accents the differences and passing of time. One of my favorites. 10', '2004-11-23 07:02:58.000000', NULL, 1),
(1028511, 123115, 24065, '<td valign="top">This was the first thumbnail to catch my eye.  I really like it.  It is well-focused and good choice of dof.  It definitely has the feel of "time passing." However, there is something about the composition that keeps me from giving it top scores.  I wish I knew enough about composition to tell you what it is!  Sorry I can''t be more concrete in suggesting an alternative.  I particularly don''t like the point of the pencil facing out.  Perhaps someone with more art background can help more.  Anyway, it''s still one of my favorites.  :D</td>', 'This was the first thumbnail to catch my eye.  I really like it.  It is well-focused and good choice of dof.  It definitely has the feel of "time passing." However, there is something about the composition that keeps me from giving it top scores.  I wish I knew enough about composition to tell you what it is!  Sorry I can''t be more concrete in suggesting an alternative.  I particularly don''t like the point of the pencil facing out.  Perhaps someone with more art background can help more.  Anyway, it''s still one of my favorites.  :D', '2004-11-23 07:44:26.000000', NULL, 1),
(1028518, 123103, 29132, '<td valign="top">Love the title and concept -- well done!</td>', 'Love the title and concept -- well done!', '2004-11-23 07:50:23.000000', NULL, 1),
(1028520, 123004, 29132, '<td valign="top">Funny title, great concept that fits the theme of this competition perfectly!</td>', 'Funny title, great concept that fits the theme of this competition perfectly!', '2004-11-23 07:54:31.000000', NULL, 1),
(1028528, 123003, 29132, '<td valign="top">The lighting, the background, the concept -- all captivating! Would love to see more photos like this.</td>', 'The lighting, the background, the concept -- all captivating! Would love to see more photos like this.', '2004-11-23 08:01:18.000000', NULL, 1),
(1028610, 122699, 26464, '<td valign="top">was this done at a museum? good concept<br/> <br/> <br/></td>', 'was this done at a museum? good concept  ', '2004-11-23 09:35:35.000000', NULL, 1),
(1028626, 122783, 9939, '<td valign="top">Great shot- I  normally don''t like mid-day, well defined shadows, but here they work very well. Nicely done.</td>', 'Great shot- I  normally don''t like mid-day, well defined shadows, but here they work very well. Nicely done.', '2004-11-23 10:06:01.000000', NULL, 1),
(1028629, 122816, 9939, '<td valign="top">Very interesting shot- I''ll be curious to learn how this was done.</td>', 'Very interesting shot- I''ll be curious to learn how this was done.', '2004-11-23 10:06:33.000000', NULL, 1),
(1028630, 123052, 14603, '<td valign="top">Very poignant shot..and quite difficult to handle, exposure wise but you`ve done well in my opinion..nice framing also.</td>', 'Very poignant shot..and quite difficult to handle, exposure wise but you`ve done well in my opinion..nice framing also.', '2004-11-23 10:09:09.000000', NULL, 1),
