(1028636, 122440, 9939, '<td valign="top">Nicely done.</td>', 'Nicely done.', '2004-11-23 10:09:53.000000', NULL, 1),
(1028637, 123128, 9939, '<td valign="top">I was hoping someone would do one of these- very nice.</td>', 'I was hoping someone would do one of these- very nice.', '2004-11-23 10:10:21.000000', NULL, 1),
(1028638, 123062, 9939, '<td valign="top">Good find! Well shot.</td>', 'Good find! Well shot.', '2004-11-23 10:11:21.000000', NULL, 1),
(1028639, 123170, 9939, '<td valign="top">Perfect clock to use for this challenge- well shot!</td>', 'Perfect clock to use for this challenge- well shot!', '2004-11-23 10:11:53.000000', NULL, 1),
(1028640, 123096, 9939, '<td valign="top">Great find, great title, great shot.</td>', 'Great find, great title, great shot.', '2004-11-23 10:13:37.000000', NULL, 1),
(1028644, 122186, 14603, '<td valign="top">I think you could be in danger of gaining around three of your personal goals with this pic Bob?<br/>The only minor quib is that you`ve left the wrinkles and saggy skin out <br/>Take it from one who knows :)<br/>Great shot, well done</td>', 'I think you could be in danger of gaining around three of your personal goals with this pic Bob?The only minor quib is that you`ve left the wrinkles and saggy skin out Take it from one who knows :)Great shot, well done', '2004-11-23 10:18:11.000000', NULL, 1),
(1028648, 122952, 14603, '<td valign="top">I like how you have included the generations in the picture to emphasise the different stages of development...this makes the tie in with the challenge criteria much stronger.</td>', 'I like how you have included the generations in the picture to emphasise the different stages of development...this makes the tie in with the challenge criteria much stronger.', '2004-11-23 10:24:49.000000', NULL, 1),
(1028659, 123074, 14603, '<td valign="top">Ah, now this is my era...wish I had managed Woodstock though :)<br/>I love the bright, colourful approach to this..it works well at rekindling the memories for those who lived through the period and gives those who didn`t a taste of what they missed.<br/>Nicely done</td>', 'Ah, now this is my era...wish I had managed Woodstock though :)I love the bright, colourful approach to this..it works well at rekindling the memories for those who lived through the period and gives those who didn`t a taste of what they missed.Nicely done', '2004-11-23 10:31:44.000000', NULL, 1),
(1028664, 121590, 14603, '<td valign="top">Represents the theme nicely also suits the B/W approach</td>', 'Represents the theme nicely also suits the B/W approach', '2004-11-23 10:34:16.000000', NULL, 1),
(1028672, 123103, 14603, '<td valign="top">I don`t think anything invokes the feeling of the passing of time more thoroughly than a rummage through the box of old photographs.<br/>The sepia treatment has just added the final touches to the overall ambience.<br/>Very well done..my favourite so far...10</td>', 'I don`t think anything invokes the feeling of the passing of time more thoroughly than a rummage through the box of old photographs.The sepia treatment has just added the final touches to the overall ambience.Very well done..my favourite so far...10', '2004-11-23 10:39:07.000000', NULL, 1),
(1028686, 122818, 14603, '<td valign="top">I doubt if there is anybody on the site who doesn`t recognise this "little beauty" by now :)<br/>You`ve crafted the shot wonderfully as usual and I see another ribbon on the horizon.<br/>Super shot..well done.</td>', 'I doubt if there is anybody on the site who doesn`t recognise this "little beauty" by now :)You`ve crafted the shot wonderfully as usual and I see another ribbon on the horizon.Super shot..well done.', '2004-11-23 10:52:44.000000', NULL, 1),
(1028687, 123086, 14603, '<td valign="top">Unusual approach to this shot...which works well at emphasising the theme of the challenge for me.</td>', 'Unusual approach to this shot...which works well at emphasising the theme of the challenge for me.', '2004-11-23 10:54:24.000000', NULL, 1),
(1028690, 123062, 14603, '<td valign="top">Illustrates the theme well.</td>', 'Illustrates the theme well.', '2004-11-23 10:56:32.000000', NULL, 1),
