(1032754, 122380, 93, '<td valign="top">This is a great image and idea, but your lack of DOF at the edges of the photo really wreck it for me.  I might be wrong, but it seems you might have had too wide an aperature here</td>', 'This is a great image and idea, but your lack of DOF at the edges of the photo really wreck it for me.  I might be wrong, but it seems you might have had too wide an aperature here', '2004-11-25 16:17:16.000000', NULL, 1),
(1032757, 123048, 93, '<td valign="top">Really nice. I wanted to do something like this but had no long candles.</td>', 'Really nice. I wanted to do something like this but had no long candles.', '2004-11-25 16:18:37.000000', NULL, 1),
(1032759, 122528, 27524, '<td valign="top">Real good DOF...such bright rust colors.</td>', 'Real good DOF...such bright rust colors.', '2004-11-25 16:23:06.000000', NULL, 1),
(1032761, 122994, 93, '<td valign="top">This just looks very heavily photoshopped. More along the lines of digital art than a true photograph for me.   The problem with it, is that you''re trying to depict deterioration, and yet you make this photo look slick and shiny, and there seems to be a huge loss of detail in the actual aging of the castle itself.   I lose any connection with the age of the subject, because of the manipulation of the photo.</td>', 'This just looks very heavily photoshopped. More along the lines of digital art than a true photograph for me.   The problem with it, is that you''re trying to depict deterioration, and yet you make this photo look slick and shiny, and there seems to be a huge loss of detail in the actual aging of the castle itself.   I lose any connection with the age of the subject, because of the manipulation of the photo.', '2004-11-25 16:25:35.000000', NULL, 1),
(1032762, 122427, 93, '<td valign="top">What a unique idea.</td>', 'What a unique idea.', '2004-11-25 16:27:28.000000', NULL, 1),
(1032768, 123101, 93, '<td valign="top">HAHAHAAHAHAHAHAAHAHAA.<br/> <br/>Nice.</td>', 'HAHAHAAHAHAHAHAAHAHAA. Nice.', '2004-11-25 16:29:55.000000', NULL, 1),
(1032778, 122380, 11895, '<td valign="top">this would look better with more depth of field</td>', 'this would look better with more depth of field', '2004-11-25 16:38:25.000000', NULL, 1),
(1032797, 122699, 11899, '<td valign="top">Nice idea - I like this one</td>', 'Nice idea - I like this one', '2004-11-25 17:19:58.000000', NULL, 1),
