(1032847, 121590, 12611, '<td valign="top">great concept but there is a white powdery lack of contrast which is super distracting. Perhaps put the compact in the shot and take the picture with the 20D</td>', 'great concept but there is a white powdery lack of contrast which is super distracting. Perhaps put the compact in the shot and take the picture with the 20D', '2004-11-25 17:57:36.000000', NULL, 1),
(1032849, 122960, 12611, '<td valign="top">THis is a pretty good shot. I would like a composition where you see more of the girls face, IMO.</td>', 'THis is a pretty good shot. I would like a composition where you see more of the girls face, IMO.', '2004-11-25 17:58:23.000000', NULL, 1),
(1032851, 123117, 12611, '<td valign="top">Lovely yet bizarre, a beautiful effect on the house in the back. A little to wierd a shot to be considered "a fine art piece" in my opinion.</td>', 'Lovely yet bizarre, a beautiful effect on the house in the back. A little to wierd a shot to be considered "a fine art piece" in my opinion.', '2004-11-25 18:00:24.000000', NULL, 1),
(1032853, 123090, 12611, '<td valign="top">Too pink. Too much of a snapshot. and worst yet- no gratuitous thong-clad arses.</td>', 'Too pink. Too much of a snapshot. and worst yet- no gratuitous thong-clad arses.', '2004-11-25 18:01:14.000000', NULL, 1),
(1032854, 121860, 12611, '<td valign="top">I love the scratches on the dial and a pretty good portrayal of stainless steel.</td>', 'I love the scratches on the dial and a pretty good portrayal of stainless steel.', '2004-11-25 18:01:41.000000', NULL, 1),
(1032856, 123096, 12611, '<td valign="top">Pretty good- It looks cropped.Nice colors.A little bit busy on the composition, I would crop it to shorten th evertical rise.</td>', 'Pretty good- It looks cropped.Nice colors.A little bit busy on the composition, I would crop it to shorten th evertical rise.', '2004-11-25 18:03:17.000000', NULL, 1),
(1032859, 121554, 12611, '<td valign="top">Pretty good- I do not like the glasses on the guy behind the wheel. Its just a nitpick. Sorry.</td>', 'Pretty good- I do not like the glasses on the guy behind the wheel. Its just a nitpick. Sorry.', '2004-11-25 18:03:55.000000', NULL, 1),
(1032860, 122999, 12611, '<td valign="top">This is disturbing. THis dog looks like Sammy Hagar after too many tequila shots. SEriously, th ecrop is tooo tight. Back it up there partner.</td>', 'This is disturbing. THis dog looks like Sammy Hagar after too many tequila shots. SEriously, th ecrop is tooo tight. Back it up there partner.', '2004-11-25 18:05:12.000000', NULL, 1),
(1032863, 123099, 12611, '<td valign="top">Interesting but the thick border and framing effect got to go.You don''t need it- the crop is too tight on the vertical as well.</td>', 'Interesting but the thick border and framing effect got to go.You don''t need it- the crop is too tight on the vertical as well.', '2004-11-25 18:06:23.000000', NULL, 1),
(1032864, 122957, 12611, '<td valign="top">This has a lot of noise and is blatantly digitized. Either it is a crop or a very bad setting.</td>', 'This has a lot of noise and is blatantly digitized. Either it is a crop or a very bad setting.', '2004-11-25 18:07:19.000000', NULL, 1),
(1032866, 122528, 12611, '<td valign="top">I love the colors and abstract qualities of the rust. Nice one here.</td>', 'I love the colors and abstract qualities of the rust. Nice one here.', '2004-11-25 18:07:55.000000', NULL, 1),
(1032868, 121935, 12611, '<td valign="top">THis is an ok foliage shot. TOo much crappy blue sky. Nice barmn placement though.</td>', 'THis is an ok foliage shot. TOo much crappy blue sky. Nice barmn placement though.', '2004-11-25 18:08:37.000000', NULL, 1),
(1032869, 122186, 12611, '<td valign="top">Too disturbing. THe blown out white side is distracting- I wish it was like the part behind your head.</td>', 'Too disturbing. THe blown out white side is distracting- I wish it was like the part behind your head.', '2004-11-25 18:09:51.000000', NULL, 1),
(1032870, 123022, 12611, '<td valign="top">Can I get a subscription?<br/>Now thats one magazine you can sue for carpal tunnel syndrome.</td>', 'Can I get a subscription?Now thats one magazine you can sue for carpal tunnel syndrome.', '2004-11-25 18:10:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1032871, 123106, 12611, '<td valign="top">Interesting, but the shapes on the left are distracting.</td>', 'Interesting, but the shapes on the left are distracting.', '2004-11-25 18:11:21.000000', NULL, 1),
(1032874, 122433, 12611, '<td valign="top">Why colorize the ring? what is the significance? Nice shot but no need.</td>', 'Why colorize the ring? what is the significance? Nice shot but no need.', '2004-11-25 18:14:14.000000', NULL, 1),
(1032875, 123083, 21714, '<td valign="top">I find the elements in the image interesting and I quite like the contrast. But I think that the quality of the image doesn''t bring out the beauty of the scenary. It''s hard to see much detail and size of the image and  it look like it''s a small crop of a much larger image.</td>', 'I find the elements in the image interesting and I quite like the contrast. But I think that the quality of the image doesn''t bring out the beauty of the scenary. It''s hard to see much detail and size of the image and  it look like it''s a small crop of a much larger image.', '2004-11-25 18:20:00.000000', NULL, 1),
(1032931, 122836, 11899, '<td valign="top">Good Job</td>', 'Good Job', '2004-11-25 20:14:15.000000', NULL, 1),
(1032950, 121732, 11653, '<td valign="top">Nice colors but I don''t care for the soft focus here</td>', 'Nice colors but I don''t care for the soft focus here', '2004-11-25 20:50:52.000000', NULL, 1),
(1032951, 122107, 11653, '<td valign="top">too much photoshop for my tastes</td>', 'too much photoshop for my tastes', '2004-11-25 20:51:16.000000', NULL, 1),
(1032952, 123045, 11653, '<td valign="top">I appreciate your attempt to show time passing</td>', 'I appreciate your attempt to show time passing', '2004-11-25 20:52:47.000000', NULL, 1),
(1032955, 123146, 11653, '<td valign="top">nice composition but doesn''t seem to meet challenge topic</td>', 'nice composition but doesn''t seem to meet challenge topic', '2004-11-25 20:54:02.000000', NULL, 1),
(1032956, 123032, 11653, '<td valign="top">This would work better if the rings of the tree could be seen more clearly</td>', 'This would work better if the rings of the tree could be seen more clearly', '2004-11-25 20:56:24.000000', NULL, 1),
(1032957, 122999, 11653, '<td valign="top">I don''t feel this meets challenge topic. However I really like the image</td>', 'I don''t feel this meets challenge topic. However I really like the image', '2004-11-25 20:57:24.000000', NULL, 1),
(1032967, 122744, 29280, '<td valign="top">I really like this idea, and think it would have been even better with a greater dof.</td>', 'I really like this idea, and think it would have been even better with a greater dof.', '2004-11-25 21:30:05.000000', NULL, 1),
(1032971, 122951, 29280, '<td valign="top">very very nice! I love the streaks you were able to get.</td>', 'very very nice! I love the streaks you were able to get.', '2004-11-25 21:31:38.000000', NULL, 1),
(1032973, 122028, 29280, '<td valign="top">I like the shot a lot, but the color chosen is a bit off putting, perhaps a touch too bright, but it could just be my monitor.</td>', 'I like the shot a lot, but the color chosen is a bit off putting, perhaps a touch too bright, but it could just be my monitor.', '2004-11-25 21:35:15.000000', NULL, 1),
