INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1047916, 122954, 6202, '<td valign="top"><br/> <br/>Very interesting take on the challenge. Fits very well.  Only thing I would have done differently is show the base of the candle also.  It''s questionable as it is if the candles are just staggered or if they really have melted down at different lengths of time.<br/> <br/>Anna<br/><br/><i>Message edited by HBunch - Removed Crit Club status.</i></td>', ' Very interesting take on the challenge. Fits very well.  Only thing I would have done differently is show the base of the candle also.  It''s questionable as it is if the candles are just staggered or if they really have melted down at different lengths of time. AnnaMessage edited by HBunch - Removed Crit Club status.', '2004-12-05 23:50:32.000000', NULL, 0),
(1047919, 122699, 6202, '<td valign="top">Critique Club<br/> <br/>Fantastic image.  Really don''t know what I would do to improve it...kinda hard to improve on a first place finish.  Well done and congrats on the finishing.<br/> <br/>Oh ok only thing that I don''t like is the missing foot...oh and that is getting really picky to even come up with that.  <br/> <br/>Fantastic take on the challenge congrats again.<br/> <br/>Anna</td>', 'Critique Club Fantastic image.  Really don''t know what I would do to improve it...kinda hard to improve on a first place finish.  Well done and congrats on the finishing. Oh ok only thing that I don''t like is the missing foot...oh and that is getting really picky to even come up with that.   Fantastic take on the challenge congrats again. Anna', '2004-12-05 23:52:51.000000', NULL, 0),
(1047922, 121122, 6202, '<td valign="top"><br/>Looking at this it fits the challenge. What I think could improve it is more negative space under the water droplet it just seems too tight at the bottom.<br/><br/><i>Message edited by HBunch - Removed Critique Club Status.</i></td>', 'Looking at this it fits the challenge. What I think could improve it is more negative space under the water droplet it just seems too tight at the bottom.Message edited by HBunch - Removed Critique Club Status.', '2004-12-05 23:54:06.000000', NULL, 0),
(1048606, 121122, 24494, '<td valign="top">thanks</td>', 'thanks', '2004-12-06 10:23:54.000000', NULL, 0),
(1050029, 122367, 23478, '<td valign="top">Thanks for all of the comments.  <br/> <br/>My challenge entry was totally unplanned. I was holding my 2 month old daughter with my camera beside me on the table. She latched on to my thumb. I set the camera on macro, took three or four shots and this was the best.  That is one reason my daughter''s hand looks a little washed out, because of the flash at such close range.  Also, I mostly desaturated the color here, like in the -80% range.  It was mostly reds.  I did it the "legal" way as explained in the tutorial.  <br/> <br/>I am happy there were no "1"s or "2"s on the scoring.</td>', 'Thanks for all of the comments.   My challenge entry was totally unplanned. I was holding my 2 month old daughter with my camera beside me on the table. She latched on to my thumb. I set the camera on macro, took three or four shots and this was the best.  That is one reason my daughter''s hand looks a little washed out, because of the flash at such close range.  Also, I mostly desaturated the color here, like in the -80% range.  It was mostly reds.  I did it the "legal" way as explained in the tutorial.   I am happy there were no "1"s or "2"s on the scoring.', '2004-12-07 08:01:46.000000', NULL, 0),
(1050649, 122816, 30303, '<td valign="top">I think the story behind this shot makes the whole piece seem even more valuable.  Wonderful photo :)</td>', 'I think the story behind this shot makes the whole piece seem even more valuable.  Wonderful photo :)', '2004-12-07 18:33:28.000000', NULL, 0),
(1057973, 122470, 29168, '<td valign="top">Very surprised to see 1''s and 2''s for this effort. The composition and subject are right on target and deserve much better on their own.<br/> <br/>Voters should keep in mind that not everyone can afford Canon EOS 300D''s or Nikon D10, D70''s, et al! Perhaps the focus is a little soft, but otherwise, very well done! Do not be discouraged.</td>', 'Very surprised to see 1''s and 2''s for this effort. The composition and subject are right on target and deserve much better on their own. Voters should keep in mind that not everyone can afford Canon EOS 300D''s or Nikon D10, D70''s, et al! Perhaps the focus is a little soft, but otherwise, very well done! Do not be discouraged.', '2004-12-12 03:11:28.000000', NULL, 0),
(1076587, 123096, 23577, '<td valign="top">Great texture shot! Great work</td>', 'Great texture shot! Great work', '2004-12-24 15:06:49.000000', NULL, 0),
